int main(int argc,char** argv){QCoreApplication app(argc,argv);try{CHECK(argc==5);auto source=std::filesystem::path(argv[1]),data=std::filesystem::path(argv[2]),bin=std::filesystem::path(argv[3]),sys=std::filesystem::path(argv[4]);auto application=stage(source,data,bin,sys),root=data/"library";reader::importFile(application,root,source/"fixtures/library/authored-three-pages.pdf",std::atomic<bool>{false});using A=ux::StatusTestAccess;const qint64 winter=QDateTime(QDate(2026,1,15),QTime(12,0),QTimeZone::utc()).toSecsSinceEpoch();
 {ux::Shell shell(application,root,true,false,false);Canvas canvas(shell);shell.tick();canvas.changes();auto tap=[&](int id,int kind=0){auto r=(kind==1?A::picker(shell):kind==2?A::keyboard(shell):A::library(shell)).rect(id);CHECK(!r.empty());CHECK(shell.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2));canvas.changes();};tap(ib::library::Menu);tap(ib::library::NavBase+int(ib::library::Section::Settings));tap(ib::settings::PageBase+int(ib::settings::Page::General));tap(ib::settings::TimeZone);CHECK(A::choosing(shell)&&!shell.statusAvailable()&&!shell.writable());ux::sharedClipboard()="Chicago";tap(ux::TimezoneView::Search,1);tap(ib::KeyPaste,2);tap(ib::KeyDone,2);{QImage frame(reinterpret_cast<const unsigned char*>(canvas.pixels.data()),1620,2160,1632*4,QImage::Format_RGB32);CHECK(frame.save(QString::fromStdString((data/"timezone-picker.png").string()),"PNG"));}tap(ux::TimezoneView::ZoneBase,1);CHECK(!A::choosing(shell)&&clockprefs::load(root).zone=="America/Chicago");A::clock(shell,winter);canvas.changes();CHECK(A::model(shell).clock=="06:00");CHECK(shell.choose(0));canvas.ready();CHECK(A::model(shell).clockOnly&&shell.page()==0);CHECK(shell.finish(5000)&&!shell.unsaved());}
 {ux::Shell reopened(application,root,true,false,false);Canvas canvas(reopened);A::clock(reopened,winter);canvas.changes();CHECK(A::model(reopened).clock=="06:00"&&!A::model(reopened).clockOnly);CHECK(reopened.choose(0));canvas.ready();CHECK(A::model(reopened).clockOnly&&reopened.page()==0&&clockprefs::load(root).zone=="America/Chicago");CHECK(reopened.finish(5000)&&!reopened.unsaved());}{ux::Shell locked(application,root,true,false,false);Canvas canvas(locked);A::pickerOpen(locked);canvas.changes();auto picker=canvas.pixels;A::lock(locked);canvas.changes();CHECK(canvas.pixels==A::lockPixels(locked)&&canvas.pixels!=picker&&!locked.writable());A::unlock(locked);canvas.changes();CHECK(canvas.pixels==picker&&A::choosing(locked));CHECK(locked.finish(5000));std::puts("TIMEZONE_LOCK_PRIORITY_PASS opaque_lock_over_picker=true picker_context_restored=true fake_state_only=true physical=NOT_RUN");}ux::sharedClipboard().clear();std::puts("TIMEZONE_ROUTE_PASS settings_picker=true native_keyboard_search=true persistent_reopen=true reader_clock_only=true actual_tablet=NOT_RUN");return 0;}catch(const std::exception& e){std::fprintf(stderr,"TIMEZONE_ROUTE_FAIL %s\n",e.what());return 1;}}
